"""Wire ``on_turn_started`` / ``on_turn_finished`` around one Mantle turn."""

from __future__ import annotations

import asyncio
from typing import TYPE_CHECKING, Literal, Optional

import structlog

from rasa.mantle.hooks.constants import POINT_TURN_FINISHED, POINT_TURN_STARTED
from rasa.mantle.hooks.payloads import TurnFinishedPayload, TurnStartedPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_observers
from rasa.mantle.hooks.utils import hook_identity
from rasa.mantle.orchestration.turn_context import current_turn_context

if TYPE_CHECKING:
    from rasa.mantle.orchestration.responses import TurnResult

structlogger = structlog.get_logger()

TurnFinishedStatus = Literal["completed", "cancelled", "error"]


def turn_finished_status(turn_result: Optional["TurnResult"]) -> TurnFinishedStatus:
    """Map a ``TurnResult`` (or a raised ``run_turn``) to ``TurnFinished.status``."""
    if turn_result is None:
        return "error"
    if turn_result.cancelled:
        return "cancelled"
    if turn_result.error:
        return "error"
    return "completed"


def fire_turn_started(registry: HookRegistry) -> asyncio.Task[None] | None:
    """Schedule ``on_turn_started`` observers without awaiting them.

    The returned task is only for tests that need to wait for completion.
    """
    if not registry.observers(POINT_TURN_STARTED):
        return None

    try:
        sender_id, channel = hook_identity()
        is_voice = current_turn_context().turn.is_voice
    except LookupError:
        # Live turns establish MessageTurnContext before these fire; missing
        # context is misuse (e.g. isolated unit tests). Skip observers.
        structlogger.warning(
            "mantle.hooks.turn_started.skipped_no_turn_context",
        )
        return None

    payload = TurnStartedPayload(
        sender_id=sender_id,
        channel=channel,
        is_voice=is_voice,
    )
    return run_observers(registry, POINT_TURN_STARTED, payload)


def fire_turn_finished(
    registry: HookRegistry,
    turn_result: Optional["TurnResult"],
) -> asyncio.Task[None] | None:
    """Schedule ``on_turn_finished`` observers without awaiting them.

    Pass ``turn_result=None`` when ``run_turn`` raised so status is ``error``.
    The returned task is only for tests that need to wait for completion.
    """
    if not registry.observers(POINT_TURN_FINISHED):
        return None

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext before these fire; missing
        # context is misuse (e.g. isolated unit tests). Skip observers.
        structlogger.warning(
            "mantle.hooks.turn_finished.skipped_no_turn_context",
        )
        return None

    payload = TurnFinishedPayload(
        sender_id=sender_id,
        channel=channel,
        status=turn_finished_status(turn_result),
    )
    return run_observers(registry, POINT_TURN_FINISHED, payload)
